class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        dct = defaultdict(list)
        indegree = {r: 0 for r in recepies}
        n = len(recepies)

        for i in range(n):
            for ing in ingredients[i]:
                dct[ing].append(recepies[i])
                indegree[recepies[i]] += 1

        q = deque(supplies)
        flst = []

        while q:
            x = q.popleft()
            for r in dct[x]:
                indegree[r] -= 1
                if indegree[r] == 0:
                    flst.append(r)
                    q.append(r)

        return flst

