class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int)  # net out degree
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        start = pairs[0][0]
        for k, v in degree.items():
            if v == 1:
                start = k
                break

        ans: List[int] = []

        def fn(x: int) -> None:
            """Return Eulerian path via dfs."""
            while graph[x]:
