class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False

        pos = defaultdict(deque)
        for idx, ch in enumerate(t):
            pos[ch].append(idx)

        a = []
        for ch in s:
            a.append(pos[ch].popleft())

        n = len(a)
        bt = BIT(n)

        last = defaultdict(lambda: -1)
        for i in range(n):
            inv = bt.sum(n - 1) - bt.sum(a[i])
            bt.update(a[i], 1)

            cur_digit = int(s[i])
            for dig in range(cur_digit - 1, -1, -1):
                if last[dig] >= i - inv:
                    return False
            last[cur_digit] = i - inv

        return True

