import collections

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words:
            return []
        wlen = len(words[0])
        if wlen == 0:
            return []
        slen = wlen * len(words)
        if slen > len(s):
            return []

        occ = collections.Counter(words)
        res: List[int] = []

        def matches(track: dict) -> bool:
            for key, val in track.items():
                if val != occ.get(key, 0):
                    return False
            for key, val in occ.items():
                if track.get(key, 0) != val:
                    return False
            return True

        for k in range(wlen):
            track = dict.fromkeys(occ.keys(), 0)

            for j in range(k, min(k + slen, len(s)), wlen):
                w = s[j:j + wlen]
                if w in occ:
                    track[w] += 1

            if k + slen <= len(s) and matches(track):
                res.append(k)

            for i in range(k + wlen, len(s) - slen + 1, wlen):
                pw = s[i - wlen:i]
                nw = s[i + slen - wlen:i + slen]
                if pw in occ:
                    track[pw] -= 1
                if nw in occ:
                    track[nw] += 1
                if matches(track):
                    res.append(i)

        return res

