class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                t = t.setdefault(c, {})
            t["end"] = True

        def first_forbidden_len(s):
            t = trie
            for idx, c in enumerate(s, 1):
                if c not in t:
                    return 0
                t = t[c]
                if "end" in t:
                    return idx
            return 0

        res = 0
        j = len(word)
        for i in range(len(word) - 1, -1, -1):
            k = first_forbidden_len(word[i:j])
            if k:
                j = min(j, i + k - 1)
            res = max(res, j - i)
