import collections

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words:
            return []
        wlen = len(words[0])
        if wlen == 0:
            return []
        n = len(words)
        slen = wlen * n
        if len(s) < slen:
            return []

        occ = collections.Counter(words)
        res: List[int] = []

        def test(track: dict) -> bool:
            return track == occ

        for k in range(wlen):
            track = {w: 0 for w in occ}

            for j in range(n):
                w = s[k + j * wlen : k + (j + 1) * wlen]
                if w in occ:
                    track[w] += 1

            if test(track):
                res.append(k)

            for i in range(k + wlen, len(s) - slen + 1, wlen):
                pw = s[i - wlen : i]
                nw = s[i + slen - wlen : i + slen]

                if pw in occ:
                    track[pw] -= 1
                if nw in occ:
                    track[nw] += 1

                if test(track):
                    res.append(i)

