        if rows == 1:
            return encoded_text

        N = len(encoded_text)
        cols = N // rows

        original_text = []
        for start_col in range(cols):
            r, c = 0, start_col
            while r < rows and c < cols:
                original_text.append(encoded_text[r * cols + c])
                r += 1
                c += 1

