class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        dct = defaultdict(list)
        indegree = defaultdict(int)
        n = len(recepies)

        for r in recepies:
            indegree[r] = 0

        for i in range(n):
            for ing in ingredients[i]:
                indegree[ing] += 0
                dct[ing].append(recepies[i])
                indegree[recepies[i]] += 1

        q = deque([x for x in indegree if indegree[x] == 0])
        flst = []
        ans = defaultdict(list)

        while q:
            x = q.popleft()
            for r in dct[x]:
                for dep in ans[x]:
                    if dep not in ans[r]:
                        ans[r].append(dep)
                if x not in ans[r]:
                    ans[r].append(x)
                indegree[r] -= 1
                if indegree[r] == 0:
                    q.append(r)

            if x in recepies:
                if all(k in supplies for k in ans[x]):
                    flst.append(x)
                    supplies.append(x)

