class Solution:
    def smallestString(self, s: str) -> str:
        # If all chars same and not all 'a', decrement all
        if len(set(s)) == 1 and s[0] != 'a':
            return ''.join(chr(ord(c) - 1) for c in s)

        # Count leading 'a's
        i = 0
        while i < len(s) and s[i] == 'a':
            i += 1
        prefix = 'a' * i
        rest = s[i:]

        # Decrement first contiguous block of non-'a'
        j = 0
        out = []
        while j < len(rest) and rest[j] != 'a':
            out.append(chr(ord(rest[j]) - 1))
            j += 1

        if out:
            return prefix + ''.join(out) + rest[j:]

        # All remaining are 'a' (or string all 'a'): change last char to 'z'
        return s[:-1] + 'z'

