from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 1000000007
        self.r = len(pizza)
        self.c = len(pizza[0])

        self.pfsum_row = []
        self.pfsum_col = []

        col_prev = [0] * self.c
        tot_apples = 0
        for i in range(self.r):
            pfr = 0
            pfs_r = [0] * self.c
            pfs_c = [0] * self.c
            for j in range(self.c):
                pfs_c[j] = col_prev[j]
                if pizza[i][j] == 'A':
                    pfr += 1
                    pfs_c[j] += 1
                    tot_apples += 1
                pfs_r[j] = pfr
            self.pfsum_row.append(pfs_r)
            self.pfsum_col.append(pfs_c)
            col_prev = pfs_c

        if tot_apples < k:
            return 0
        if k == 1:
            return 1
        return self.getWays(0, 0, k) % MOD

    @lru_cache(None)
    def getWays(self, i: int, j: int, k: int) -> int:
        if k == 1:
            for c in range(j, self.c):
                apples = self.pfsum_col[self.r - 1][c] - (self.pfsum_col[i - 1][c] if i > 0 else 0)
                if apples:
                    return 1
            return 0

        t_cnt = 0
        cannot_cut = True
        nr = i
        while nr < self.r - 1:
            while nr < self.r - 1 and cannot_cut:
                apples = self.pfsum_row[nr][self.c - 1] - (self.pfsum_row[nr][j - 1] if j > 0 else 0)
                if apples:
                    cannot_cut = False
                else:
                    nr += 1
            if nr < self.r - 1:
                t_cnt += self.getWays(nr + 1, j, k - 1)
            nr += 1

        cannot_cut = True
        nc = j
        while nc < self.c - 1:
            while nc < self.c - 1 and cannot_cut:
                apples = self.pfsum_col[self.r - 1][nc] - (self.pfsum_col[i - 1][nc] if i > 0 else 0)
                if apples:
                    cannot_cut = False
                else:
                    nc += 1
            if nc < self.c - 1:
                t_cnt += self.getWays(i, nc + 1, k - 1)
            nc += 1

        return t_cnt

from collections import defaultdict

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        rec, track = [0], defaultdict(int)
        ct = start = 0

        while True:
            for ch in s2:
                ptr = s1.find(ch, start)
                if ptr == -1:
                    ct += 1
                    ptr = s1.find(ch, 0)
                start = ptr + 1
                if start == len(s1):
                    ct += 1
                    start = 0

            rec.append(ct)
            if rec[-1] > n1:
                return (len(rec) - 2) // n2

            state = start
            if state not in track:
                track[state] = len(rec) - 1
            else:
                break

        cycleStart = rec[track[state]]
        cycle1 = ct - cycleStart
        cycle2 = (len(rec) - 1) - track[state]
        rest = n1 - cycleStart
        rem = cycleStart + (rest % cycle1)

        ptr2 = 0
        while ptr2 < len(rec) and rec[ptr2] <= rem:
            ptr2 += 1

        return (cycle2 * (rest // cycle1) + (ptr2 - 1)) // n2
